/*
 * SEGGER SystemView setup for the Kepler demo: timestamps, the description
 * SystemView shows, interrupt names, and the values it plots.
 *
 * See documentation/tracing_systemview.md.
 */
#include "trace.h"

#if FW_SYSVIEW

#include "main.h"            /* CMSIS: CoreDebug, DWT, SystemCoreClock */
#include "FreeRTOS.h"
#include "task.h"
#include "SEGGER_SYSVIEW.h"
#include "fw_version.h"      /* generated by app/Makefile from git describe */
#include "log.h"

/* SystemView's FreeRTOS interface, in SEGGER_SYSVIEW_FreeRTOS.c */
extern const SEGGER_SYSVIEW_OS_API SYSVIEW_X_OS_TraceAPI;

/* Lowest RAM address. SystemView sends object addresses relative to it,
 * which makes each event a few bytes shorter. */
#define TRACE_RAM_BASE        0x20000000u

/* 1: start recording at boot, so start-up events wait in the RTT buffer
 * until the SystemView app connects. 0: record only once the app starts
 * recording. Override with -DTRACE_RECORD_FROM_BOOT=0. */
#ifndef TRACE_RECORD_FROM_BOOT
#define TRACE_RECORD_FROM_BOOT 1
#endif

/* How often trace_periodic() logs a status line */
#define TRACE_STATUS_PERIOD_MS 10000u

/* Plotted values. SystemView reads them through these IDs. */
enum
{
  PLOT_FREE_HEAP     = 0,
  PLOT_MIN_FREE_HEAP = 1,
};

static U32 free_heap;
static U32 min_free_heap;

/*
 * Start the Cortex-M7 cycle counter, which SystemView reads for timestamps
 * (DWT_CYCCNT, at 0xE0001004). On the M7 the DWT's lock register has to be
 * unlocked before software can enable it.
 */
static void cycle_counter_start(void)
{
  CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
  DWT->LAR = 0xC5ACCE55u;
  DWT->CYCCNT = 0u;
  DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}

static void register_plot(U32 id, const char *name, const char *unit)
{
  SEGGER_SYSVIEW_DATA_REGISTER reg = {
    .ID            = id,
    .DataType      = SEGGER_SYSVIEW_TYPE_U32,
    .Offset        = 0,
    .RangeMin      = 0,
    .RangeMax      = 0,
    .ScalingFactor = 0.0f,
    .sName         = name,
    .sUnit         = unit,
  };

  SEGGER_SYSVIEW_RegisterData(&reg);
}

/*
 * Called by SystemView each time the SystemView app starts recording. It
 * describes the system, names the interrupts, and registers the plotted
 * values; SystemView doesn't remember registrations between recordings.
 *
 * Interrupt numbers are the exception numbers SystemView reads from the
 * ICSR register: the CMSIS IRQn plus 16.
 */
static void send_system_description(void)
{
  SEGGER_SYSVIEW_SendSysDesc("N=Kepler demo " FW_VERSION ",D=STM32F746NG,O=FreeRTOS");
  SEGGER_SYSVIEW_SendSysDesc("I#15=SysTick,I#35=CAN1_TX,I#36=CAN1_RX0");
  SEGGER_SYSVIEW_SendSysDesc("I#37=CAN1_RX1,I#38=CAN1_SCE,I#53=USART1");
  SEGGER_SYSVIEW_SendSysDesc("I#70=TIM6 HAL tick,I#74=USART1 RX DMA");
  SEGGER_SYSVIEW_SendSysDesc("I#77=ETH,I#86=USART1 TX DMA");

  register_plot(PLOT_FREE_HEAP, "Free heap", "bytes");
  register_plot(PLOT_MIN_FREE_HEAP, "Lowest free heap", "bytes");
}

void trace_init(void)
{
  cycle_counter_start();

  /* SystemCoreClock is 216 MHz once SystemClock_Config() has run */
  SEGGER_SYSVIEW_Init(SystemCoreClock, SystemCoreClock,
                      &SYSVIEW_X_OS_TraceAPI, send_system_description);
  SEGGER_SYSVIEW_SetRAMBase(TRACE_RAM_BASE);
}

/*
 * A reset clears the RTT buffer and stops the app's recording, so start-up
 * can't be recorded from the PC. Starting here keeps start-up events in the
 * buffer instead; once it's full, newer events are dropped until the app
 * reads it. When the app then starts recording, SystemView starts again
 * (SEGGER_SYSVIEW_CAN_RESTART is 1) and resends the system description.
 *
 * Must not run before the scheduler starts. SEGGER_SYSVIEW_Start() reads the
 * time through xTaskGetTickCountFromISR(), whose configASSERT() fails until
 * vTaskStartScheduler() has set up the port's interrupt priority check; the
 * failed assert stops the CPU with interrupts off.
 */
void trace_start(void)
{
#if TRACE_RECORD_FROM_BOOT
  SEGGER_SYSVIEW_Start();
#endif
}

static void sample(U32 id, U32 *value)
{
  SEGGER_SYSVIEW_DATA_SAMPLE s = { .ID = id, .pValue.pU32 = value };

  SEGGER_SYSVIEW_SampleData(&s);
}

void trace_periodic(void)
{
  static TickType_t last_status;
  TickType_t now = xTaskGetTickCount();

  free_heap = (U32)xPortGetFreeHeapSize();
  min_free_heap = (U32)xPortGetMinimumEverFreeHeapSize();
  sample(PLOT_FREE_HEAP, &free_heap);
  sample(PLOT_MIN_FREE_HEAP, &min_free_heap);

  if ((now - last_status) >= pdMS_TO_TICKS(TRACE_STATUS_PERIOD_MS))
  {
    last_status = now;
    LOG("Status: up %u s, free heap %u bytes, lowest %u bytes",
        (unsigned)(now / configTICK_RATE_HZ), (unsigned)free_heap,
        (unsigned)min_free_heap);
  }
}

#endif /* FW_SYSVIEW */
